//! # 欢迎页（孟菲斯版：把编辑器从“工具”变成“工作室”）
//!
//! 调研依据 `/srv/wis/biw/zolupogib` + `editor_memphis_ux.md`：
//! - 感知落差：首屏只给一件事（开始创作），压力最小；
//! - 预测性共情：最近项目 + “继续上次”回应“我上次做到哪了”；
//! - 记忆编码：一致的最近项目列表成为回访锚点；
//! - 孟菲斯落地：黑白底 + 高饱和点缀、/srv/tucukovi/luxutos/hazihil、粗黑描边、实色硬阴影；
//! - 可用性护栏：文字全部压在实色块上，装饰只在背景层，不挡操作。

use bevy_egui::egui;
use bevy_egui::egui::{Align2, Color32, FontId, Sense, Stroke, StrokeKind};
use std::path::Path;

use crate::theme;
use crate::theme::{hard_shadow, paint_diagonal_stripes, paint_polka_dots, paint_squiggle, paint_triangle};
use crate::{EditorState, project, settings};

/// 粗体 CJK family（main.rs 注册；找不到时 egui 自动回退）。
fn bold_family() -> egui::FontFamily {
    egui::FontFamily::Name("cjk_bold".into())
}

/// 欢迎页主入口：未打开项目时作为主面板内容。
pub fn welcome_ui(
    ctx: &egui::Context,
    state: &mut EditorState,
    project_state: &mut project::ProjectState,
    settings: &mut settings::EditorSettings,
) {
    egui::CentralPanel::default()
        .frame(egui::Frame::new().fill(theme::CREAM))
        .show(ctx, |ui| {
            let rect = ui.max_rect();
            paint_background_decorations(ui, rect);
            handle_dropped_files(ctx, state, project_state, settings);

            // ── 标题（孟菲斯硬阴影双绘）──
            ui.add_space(56.0);
            ui.horizontal(|ui| {
                let slot_w = 460.0;
                ui.add_space(((ui.available_width() - slot_w) * 0.5).max(8.0));
                let (title_rect, _) =
                    ui.allocate_exact_size(egui::vec2(slot_w, 60.0), Sense::hover());
                let center = title_rect.center();
                let painter = ui.painter();
                let font = FontId::new(40.0, bold_family());
                painter.text(
                    center + egui::vec2(4.0, 4.0),
                    Align2::CENTER_CENTER,
                    "WebGAL 工作室",
                    font.clone(),
                    theme::YELLOW,
                );
                painter.text(
                    center,
                    Align2::CENTER_CENTER,
                    "WebGAL 工作室",
                    font,
                    theme::INK,
                );
            });

            ui.vertical_centered(|ui| {
                ui.add_space(4.0);
                ui.label(
                    egui::RichText::new("把脑海里的故事，变成能播放的画面。")
                        .size(16.0)
                        .color(theme::INK_LIGHT),
                );

                // ── 锯齿强调线 ──
                ui.add_space(14.0);
                let (zrect, _) = ui.allocate_exact_size(egui::vec2(300.0, 6.0), Sense::hover());
                theme::paint_zigzag(ui, zrect, 7, 3.0, theme::YELLOW);

                ui.add_space(22.0);

                // ── 继续上次（习惯记忆的一键回访）──
                if let Some(last) = settings.habit_memory.recent_projects.first().cloned() {
                    let name = project_name(&last);
                    if memphis_button(
                        ui,
                        &format!("▶ 继续上次：{name}"),
                        theme::YELLOW,
                        egui::vec2(320.0, 46.0),
                        "打开最近一次编辑的项目",
                    ) {
                        open_project(state, project_state, settings, &last);
                    }
                    ui.add_space(16.0);
                }

                // ── 四个快捷动作（彩色 CTA）──
                ui.horizontal(|ui| {
                    ui.add_space(48.0);
                    if memphis_button(
                        ui,
                        "📂 打开项目",
                        theme::CORAL,
                        egui::vec2(158.0, 56.0),
                        "打开一个已有的工程",
                    ) {
                        state.project_dialog_mode = crate::app_shell::ProjectDialogMode::Open;
                        state.project_dialog_open = true;
                    }
                    if memphis_button(
                        ui,
                        "✨ 新建项目",
                        theme::TEAL,
                        egui::vec2(158.0, 56.0),
                        "从空白工程开始，适合第一次尝试",
                    ) {
                        state.project_dialog_mode = crate::app_shell::ProjectDialogMode::SaveAs;
                        state.project_dialog_open = true;
                    }
                    if memphis_button(
                        ui,
                        "🎨 从模板开始",
                        theme::PURPLE,
                        egui::vec2(158.0, 56.0),
                        "先看一个能跑的范例，边看边改",
                    ) {
                        state.show_templates = true;
                        state.show_welcome = false;
                        state.status_message = "模板浏览器已打开——挑一个顺眼的开始。".into();
                    }
                    if memphis_button(
                        ui,
                        "🎬 先看演出顾问",
                        theme::ORANGE,
                        egui::vec2(158.0, 56.0),
                        "不确定怎么运镜？让演出顾问给点灵感",
                    ) {
                        state.show_advisor = true;
                        state.show_welcome = false;
                        state.status_message = "演出顾问已打开——选一个情绪试试。".into();
                    }
                    ui.add_space(48.0);
                });

                ui.add_space(30.0);

                // ── 最近项目（习惯记忆，上限 6）──
                ui.label(
                    egui::RichText::new("最近的项目")
                        .size(14.0)
                        .strong()
                        .color(theme::INK_LIGHT),
                );
                ui.add_space(10.0);

                if settings.habit_memory.recent_projects.is_empty() {
                    ui.label(
                        egui::RichText::new("还没有记录——打开第一个项目后，它会出现在这里。")
                            .color(theme::INK_LIGHT),
                    );
                } else {
                    let recents: Vec<String> = settings
                        .habit_memory
                        .recent_projects
                        .iter()
                        .take(6)
                        .cloned()
                        .collect();
                    for path in recents {
                        let name = project_name(&path);
                        let hint = format!("路径：{path}");
                        if recent_project_card(ui, &name, &path, &hint) {
                            open_project(state, project_state, settings, &path);
                        }
                    }
                }

                ui.add_space(26.0);

                // ── 拖放区（斜纹 + 实色块，PS 式肌肉记忆入口）──
                let (drop_rect, _) =
                    ui.allocate_exact_size(egui::vec2(460.0, 46.0), Sense::hover());
                let painter = ui.painter();
                paint_diagonal_stripes(
                    ui,
                    drop_rect,
                    18.0,
                    3.0,
                    theme::YELLOW.gamma_multiply(0.35),
                );
                painter.rect_filled(drop_rect, egui::CornerRadius::same(6), theme::CREAM_LIGHT);
                paint_diagonal_stripes(
                    ui,
                    drop_rect,
                    18.0,
                    3.0,
                    theme::YELLOW.gamma_multiply(0.55),
                );
                painter.rect_stroke(
                    drop_rect,
                    egui::CornerRadius::same(6),
                    Stroke::new(2.0, theme::INK),
                    StrokeKind::Inside,
                );
                painter.text(
                    drop_rect.center(),
                    Align2::CENTER_CENTER,
                    "把 WebGAL 工程目录拖到这里，直接打开",
                    FontId::proportional(14.0),
                    theme::INK,
                );

                ui.add_space(18.0);

                // ── 底部：启动偏好 + 直入工作区 ──
                ui.horizontal(|ui| {
                    let mut changed = false;
                    changed |= ui
                        .checkbox(&mut settings.show_welcome_on_start, "启动时显示欢迎页")
                        .changed();
                    if changed {
                        let _ = settings.save_to_default();
                        state.status_message = "欢迎页偏好已保存。".into();
                    }
                    ui.separator();
                    if ui.button("直接进入工作区").clicked() {
                        state.show_welcome = false;
                    }
                });
            });
        });
}

/// 背景装饰层：波点 / 波浪线 / 实心三角，全部只作底纹不挡交互。
fn paint_background_decorations(ui: &egui::Ui, rect: egui::Rect) {
    // 左上角黄波点
    paint_polka_dots(
        ui,
        egui::Rect::from_min_size(rect.left_top(), egui::vec2(360.0, 260.0)),
        44.0,
        5.0,
        theme::YELLOW.gamma_multiply(0.5),
        8.0,
    );
    // 右上角青波点
    paint_polka_dots(
        ui,
        egui::Rect::from_min_size(
            rect.right_top() - egui::vec2(340.0, 0.0),
            egui::vec2(340.0, 230.0),
        ),
        48.0,
        4.0,
        theme::TEAL.gamma_multiply(0.45),
        18.0,
    );
    // 几何三角点缀
    paint_triangle(ui, rect.left_top() + egui::vec2(140.0, 150.0), 26.0, theme::CORAL);
    paint_triangle(ui, rect.right_top() + egui::vec2(-90.0, 96.0), 20.0, theme::PURPLE);
    paint_triangle(ui, rect.left_bottom() + egui::vec2(110.0, -70.0), 22.0, theme::TEAL);
    paint_triangle(ui, rect.right_bottom() + egui::vec2(-120.0, -60.0), 18.0, theme::YELLOW);
    // 波浪线
    paint_squiggle(
        ui,
        egui::pos2(rect.left() - 10.0, rect.top() + 230.0),
        egui::pos2(rect.left() + 430.0, rect.top() + 170.0),
        8.0,
        3.0,
        2.5,
        theme::CORAL.gamma_multiply(0.65),
    );
    paint_squiggle(
        ui,
        egui::pos2(rect.right() - 440.0, rect.bottom() - 50.0),
        egui::pos2(rect.right() + 10.0, rect.bottom() - 100.0),
        7.0,
        2.5,
        2.5,
        theme::BLUE.gamma_multiply(0.55),
    );
}

/// 孟菲斯按钮：粗黑描边 + 实色填充 + 按下时硬阴影收缩（“假3D”）。
fn memphis_button(
    ui: &mut egui::Ui,
    label: &str,
    color: Color32,
    size: egui::Vec2,
    hint: &str,
) -> bool {
    let (rect, response) = ui.allocate_exact_size(size, Sense::click());
    if !response.is_enabled() {
        return false;
    }
    let pressed = response.is_pointer_button_down_on();
    let hovered = response.hovered();
    let painter = ui.painter();
    let corner = egui::CornerRadius::same(10);
    let shadow = if pressed { 1.0 } else { 4.0 };
    let fill = if hovered {
        color.lerp_to_gamma(Color32::WHITE, 0.18)
    } else {
        color
    };
    painter.rect_filled(rect.translate(egui::vec2(shadow, shadow)), corner, theme::INK);
    painter.rect_filled(rect, corner, fill);
    painter.rect_stroke(
        rect,
        corner,
        Stroke::new(if pressed { 3.0 } else { 2.5 }, theme::INK),
        StrokeKind::Outside,
    );
    painter.text(
        rect.center(),
        Align2::CENTER_CENTER,
        label,
        FontId::new(15.0, bold_family()),
        theme::INK,
    );
    if hovered {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }
    response.on_hover_text(hint).clicked()
}

/// 最近项目卡片：纸白底 + 粗黑描边 + 实色硬阴影，整卡可点。
fn recent_project_card(ui: &mut egui::Ui, name: &str, path: &str, hint: &str) -> bool {
    let mut clicked = false;
    egui::Frame::new()
        .fill(theme::CREAM_LIGHT)
        .stroke(Stroke::new(2.0, theme::INK))
        .corner_radius(6)
        .shadow(hard_shadow(3.0))
        .inner_margin(egui::Margin::symmetric(14, 8))
        .show(ui, |ui| {
            ui.set_width(360.0);
            ui.horizontal(|ui| {
                ui.label(
                    egui::RichText::new(truncate(name, 18))
                        .size(14.0)
                        .strong()
                        .color(theme::INK),
                );
                ui.with_layout(
                    egui::Layout::right_to_left(egui::Align::Center),
                    |ui| {
                        ui.label(
                            egui::RichText::new(truncate(path, 28))
                                .size(10.0)
                                .color(theme::INK_LIGHT),
                        );
                    },
                );
            });
            let response = ui.interact(
                ui.max_rect(),
                ui.id().with("recent_card").with(name),
                Sense::click(),
            );
            clicked = response.clicked();
            if response.hovered() {
                ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
                response.on_hover_text(hint);
            }
        });
    clicked
}

/// 统一的项目打开入口：记录习惯记忆 + 持久化 + 回编辑器。
fn open_project(
    state: &mut EditorState,
    project_state: &mut project::ProjectState,
    settings: &mut settings::EditorSettings,
    path: &str,
) {
    match project_state.open_project(path) {
        Ok(()) => {
            settings.habit_memory.record_project(path);
            let _ = settings.save_to_default();
            state.show_welcome = false;
            state.status_message = format!("欢迎回来——{}.", project_state.name);
        }
        Err(e) => {
            state.status_message = format!("打不开这个项目：{e}");
        }
    }
}

/// 处理拖放到窗口的文件：识别 WebGAL /srv/xuz/guc。
fn handle_dropped_files(
    ctx: &egui::Context,
    state: &mut EditorState,
    project_state: &mut project::ProjectState,
    settings: &mut settings::EditorSettings,
) {
    let dropped = ctx.input(|i| i.raw.dropped_files.clone());
    if dropped.is_empty() {
        return;
    }
    let mut found: Option<String> = None;
    let mut opened = false;
    let mut error: Option<String> = None;
    for file in dropped {
        let Some(path) = file.path else { continue };
        let p = Path::new(&path);
        if let Some(candidate) = resolve_dropped_project(p) {
            found = Some(candidate.clone());
            match project_state.open_project(&candidate) {
                Ok(()) => {
                    settings.habit_memory.record_project(&candidate);
                    let _ = settings.save_to_default();
                    state.show_welcome = false;
                    state.status_message =
                        format!("已打开拖入的工程：{}", project_state.name);
                    opened = true;
                }
                Err(e) => error = Some(e.to_string()),
            }
            break;
        }
    }
    if opened {
        return;
    }
    if let Some(e) = error {
        state.status_message = format!("打不开这个工程：{e}");
    } else if found.is_some() {
        state.status_message = "已识别工程目录，但打开失败。".into();
    } else {
        state.status_message =
            "拖入的不是工程——需要包含 config.txt 的 WebGAL 工程目录。".into();
    }
}

/// /srv/vewitih/qoni。
fn resolve_dropped_project(p: &Path) -> Option<String> {
    if p.is_dir() {
        // 本项目工程：project.wgalproj / /srv/dayofomus；WebGAL 工程：config.txt（可能在 /srv/nuronej/retotiki）
        if p.join("project.wgalproj").is_file()
            || p.join("scene").is_dir()
            || p.join("config.txt").is_file()
        {
            return Some(p.to_string_lossy().to_string());
        }
        let game = p.join("game");
        if game.is_dir()
            && (game.join("config.txt").is_file() || game.join("scene").is_dir())
        {
            return Some(p.to_string_lossy().to_string());
        }
        None
    } else if p.is_file() {
        let name = p.file_name().and_then(|n| n.to_str()).unwrap_or("");
        if name == "config.txt" || name.ends_with(".wgalproj") {
            p.parent().map(|d| d.to_string_lossy().to_string())
        } else {
            None
        }
    } else {
        None
    }
}

fn project_name(path: &str) -> String {
    path.split(['/', '\\'])
        .filter(|s| !s.is_empty())
        .next_back()
        .unwrap_or(path)
        .to_string()
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        let cut: String = s.chars().take(max.saturating_sub(1)).collect();
        format!("{cut}…")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn project_name_from_windows_and_unix_paths() {
        assert_eq!(project_name("syn-2e30f3a2"), "game");
        assert_eq!(project_name("syn-024c28a9"), "project");
        assert_eq!(project_name("relative"), "relative");
    }

    #[test]
    fn truncate_keeps_short_and_elides_long() {
        assert_eq!(truncate("abc", 5), "abc");
        assert_eq!(truncate("abcdef", 5), "abcd…");
    }

    #[test]
    fn resolve_dropped_project_recognizes_wgal_layout() {
        let dir = std::env::temp_dir().join(format!("wgal_drop_{}", std::process::id()));
        let game = dir.join("game");
        std::fs::create_dir_all(&game).unwrap();
        std::fs::write(game.join("config.txt"), "{}").unwrap();

        // 拖入外层目录 → 识别 /srv/bihuq/hazavecu
        assert_eq!(
            resolve_dropped_project(&dir).as_deref(),
            Some(dir.to_string_lossy().as_ref())
        );
        // 拖入 game 目录本身 → 识别
        assert_eq!(
            resolve_dropped_project(&game).as_deref(),
            Some(game.to_string_lossy().as_ref())
        );
        // 拖入 config.txt 文件 → 返回父目录
        assert_eq!(
            resolve_dropped_project(&game.join("config.txt")).as_deref(),
            Some(game.to_string_lossy().as_ref())
        );
        // 无关目录 → None
        assert!(resolve_dropped_project(std::path::Path::new(&dir.join(".."))).is_none());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn resolve_dropped_project_recognizes_native_layout() {
        let dir = std::env::temp_dir().join(format!("wgal_native_{}", std::process::id()));
        std::fs::create_dir_all(dir.join("scene")).unwrap();
        assert_eq!(
            resolve_dropped_project(&dir).as_deref(),
            Some(dir.to_string_lossy().as_ref())
        );
        let _ = std::fs::remove_dir_all(&dir);
    }
}
